float consistent_hash(const std::string &msg) {
    // Calculate MD5 digest of the input string
    unsigned char md5_digest[16];
    MD5((unsigned char *)msg.c_str(), msg.size(), md5_digest);

    // Sum the digest bytes with a base multiplier and return the modulo result normalized to [0,1]
    int sum = 0;
    for (int i = 0; i < 16; i++) {
        sum += md5_digest[i];
    }
    return (float)sum / (16 * 256);
}

